import{_ as t,c as o,o as a,aj as s}from"./chunks/framework.Id7s26SP.js";const p=JSON.parse('{"title":"Interface: WorkflowStatusSlice","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/WorkflowStatusSlice.md","filePath":"reference/js-bao-wss-client/api/interfaces/WorkflowStatusSlice.md"}'),r={name:"reference/js-bao-wss-client/api/interfaces/WorkflowStatusSlice.md"};function l(n,e,c,i,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / WorkflowStatusSlice</p><h1 id="interface-workflowstatusslice" tabindex="-1">Interface: WorkflowStatusSlice <a class="header-anchor" href="#interface-workflowstatusslice" aria-label="Permalink to “Interface: WorkflowStatusSlice”">​</a></h1><p>A slice record the client can vouch for. Field for field with the Swift client&#39;s <code>WorkflowSliceInfo</code>.</p><p>Timestamps are epoch milliseconds (what the route sends), not the ISO-8601 strings a run record carries — the slice record is the platform&#39;s own bookkeeping, and the client passes its numbers through verbatim.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="ceilingat" tabindex="-1">ceilingAt <a class="header-anchor" href="#ceilingat" aria-label="Permalink to “ceilingAt”">​</a></h3><blockquote><p><strong>ceilingAt</strong>: <code>number</code> | <code>null</code></p></blockquote><p>The 12-hour bound THIS slice ends at, epoch ms — <code>startedAt</code> plus the slice maximum, not a deadline for the run, which can continue in a later slice with a ceiling of its own.</p><hr><h3 id="lastrefreshat" tabindex="-1">lastRefreshAt <a class="header-anchor" href="#lastrefreshat" aria-label="Permalink to “lastRefreshAt”">​</a></h3><blockquote><p><strong>lastRefreshAt</strong>: <code>number</code> | <code>null</code></p></blockquote><p>When the credential was last refreshed, epoch ms.</p><hr><h3 id="lastresetat" tabindex="-1">lastResetAt <a class="header-anchor" href="#lastresetat" aria-label="Permalink to “lastResetAt”">​</a></h3><blockquote><p><strong>lastResetAt</strong>: <code>number</code> | <code>null</code></p></blockquote><p>When the most recent reset was counted, epoch ms; <code>null</code> until there is one.</p><hr><h3 id="lastresetcause" tabindex="-1">lastResetCause <a class="header-anchor" href="#lastresetcause" aria-label="Permalink to “lastResetCause”">​</a></h3><blockquote><p><strong>lastResetCause</strong>: <code>string</code> | <code>null</code></p></blockquote><p>What named the most recent reset: <code>&quot;code-updated&quot;</code> when the platform build changed underneath the run, <code>&quot;evicted&quot;</code> when the runtime said it had reclaimed the run&#39;s memory, <code>&quot;unknown&quot;</code> when the platform saw the run interrupted but could not attribute it. <code>null</code> until there has been one. A plain string, for the same reason <code>settledStatus</code> is one.</p><hr><h3 id="refreshcount" tabindex="-1">refreshCount <a class="header-anchor" href="#refreshcount" aria-label="Permalink to “refreshCount”">​</a></h3><blockquote><p><strong>refreshCount</strong>: <code>number</code></p></blockquote><p>How many times the credential was refreshed through the gateway instead of yielding. <code>0</code> for a run short enough never to need one.</p><hr><h3 id="resets" tabindex="-1">resets <a class="header-anchor" href="#resets" aria-label="Permalink to “resets”">​</a></h3><blockquote><p><strong>resets</strong>: <code>number</code></p></blockquote><p>How many of this run&#39;s slices the platform tore down and started again — a platform deploy interrupts every slice that is executing, and so does the runtime reclaiming memory.</p><p>The interrupted step is then run again as a further attempt, so a run that was reset and then finished reads <code>completed</code> with no failure and no error code: this count is the only place that history shows. <code>0</code> for a run nothing reset, and for a server that predates the field.</p><hr><h3 id="settledat" tabindex="-1">settledAt <a class="header-anchor" href="#settledat" aria-label="Permalink to “settledAt”">​</a></h3><blockquote><p><strong>settledAt</strong>: <code>number</code> | <code>null</code></p></blockquote><p>When THIS slice settled, epoch ms; <code>null</code> while the slice is open. A settled slice is not a finished run: a slice that yielded settles here and the run continues in the next slice, so a caller watching a run still reads <code>status</code>, never this field.</p><hr><h3 id="settledstatus" tabindex="-1">settledStatus <a class="header-anchor" href="#settledstatus" aria-label="Permalink to “settledStatus”">​</a></h3><blockquote><p><strong>settledStatus</strong>: <code>string</code> | <code>null</code></p></blockquote><p>How THIS slice settled (<code>&quot;completed&quot;</code>, <code>&quot;failed&quot;</code>, <code>&quot;cpu-yield&quot;</code>, …); <code>null</code> while the slice is open. <code>&quot;cpu-yield&quot;</code> is the slice that gave up its CPU budget for the run to carry on in another one.</p><hr><h3 id="sliceid" tabindex="-1">sliceId <a class="header-anchor" href="#sliceid" aria-label="Permalink to “sliceId”">​</a></h3><blockquote><p><strong>sliceId</strong>: <code>string</code></p></blockquote><p>Id of the slice record. The one field the server always fills.</p><hr><h3 id="startedat" tabindex="-1">startedAt <a class="header-anchor" href="#startedat" aria-label="Permalink to “startedAt”">​</a></h3><blockquote><p><strong>startedAt</strong>: <code>number</code> | <code>null</code></p></blockquote><p>When this slice started, epoch ms.</p>',47)])])}const f=t(r,[["render",l]]);export{p as __pageData,f as default};
